import org.marker.mushroom.alias.DAOimport org.marker.mushroom.core.config.impl.DataBaseConfigimport org.marker.mushroom.dao.ISupportDaoimport org.marker.mushroom.ext.plugin.Pluginletimport org.marker.mushroom.holder.SpringContextHolderimport org.marker.mushroom.utils.ResultUtilsimport org.springframework.web.bind.annotation.ResponseBodyimport javax.servlet.http.HttpServletRequest/** * 留言插件 * * * @author marker * */public class PanchaPluginletImpl extends Pluginlet {    PanchaPluginletImpl() {        this._config = [                module     : "pancha",                name       : "盘查插件",                author     : "marker",                type       : "pancha",// 模型标识                description: "常规插件"        ]        // 路由配置        this.routers = [                " get:/list.do" : "list",                " get:/edit.do": "edit",                "post:/update.do": "update",        ]    }    /**     * 显示留言列表     */    String list() {        HttpServletRequest request = getServletRequest();        int currentPageNo = 1;        try {            currentPageNo = Integer.parseInt(request.getParameter("currentPageNo"));        } catch (Exception e) {        }        ISupportDao dao = SpringContextHolder.getBean(DAO.COMMON);        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String prefix = dbcfg.getPrefix();        String sql = """select a.*,p.keywords pKeywords,p.type as pType, p.pwd from ${prefix}article a                 left join ${prefix}pancha p on a.id = p.article_id                 order by a.id desc                """;        request.setAttribute("page", dao.findByPage(currentPageNo, 15, sql));        return "list.html";    }    def page() {        HttpServletRequest request = getServletRequest();        int currentPageNo = 1;        try {            currentPageNo = Integer.parseInt(request.getParameter("currentPageNo"));        } catch (Exception e) {        }        ISupportDao dao = SpringContextHolder.getBean(DAO.COMMON);        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String prefix = dbcfg.getPrefix();        String sql = """select a.*,p.keywords pKeywords,p.type as pType, p.pwd from ${prefix}article a                 left join ${prefix}pancha p on a.id = p.article_id                 order by a.id desc                """;        return dao.findByPage(currentPageNo, 15, sql)    }    /**     * 留言审核     */    @ResponseBody    def audit() {        HttpServletRequest request = getServletRequest();        String idStr = request.getParameter("id");// id        int id = Integer.parseInt(idStr);        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String sql = "update " + dbcfg.getPrefix() + "pancha set status=1 where id=?";        Object[] params = [id] as Object[]        if (!commonDao.update(sql, params)) {            return ResultUtils.error("审核失败！")        }        return ResultUtils.success("审核成功！")    }    /**     * 更新盘查     * @return     */    @ResponseBody    def update() {        HttpServletRequest request = getServletRequest();        String idStr = request.getParameter("id");// id        String pKeywords = request.getParameter("pKeywords");// id        String pType = request.getParameter("pType");// id        String pPwd = request.getParameter("pPwd");// id        String pUrl = request.getParameter("pUrl");// id        int id = Integer.parseInt(idStr);        // TODO keywords 验重复        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String prefix = dbcfg.getPrefix();        Map<String,Object> entity = getOne(id);        if(entity != null && entity.get("pId") != null){ // 数据存在则更新            String sql = "update " + dbcfg.getPrefix() + "pancha set keywords=?,type=?,pwd=?,url=?,article_id=? where id=?";            Object[] params = [pKeywords,pType,pPwd,pUrl,id,id] as Object[]            if (commonDao.update(sql, params)) {                return ResultUtils.success("成功！")            }        }else{            String sql = "insert into " + dbcfg.getPrefix() + "pancha(id,keywords,type,pwd,url,article_id, create_time) values(?,?,?,?,?,?, sysdate())";            Object[] params = [id, pKeywords,pType,pPwd,pUrl,id] as Object[]            if (commonDao.update(sql, params)) {                return ResultUtils.success("成功！")            }        }        return ResultUtils.error("失败！")    }    /**     * 编辑盘查     */    String edit() {        HttpServletRequest request = getServletRequest();        String idStr = request.getParameter("id");// id        int id = Integer.parseInt(idStr);        request.setAttribute("article", getOne(id));         return "edit.html";    }    /**     * 前端留言组件     */    def view() {        HttpServletRequest request = getServletRequest();        return "guestbook.html";    }    // ============== 持久层 ==============    def getOne(Integer id){        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String prefix = dbcfg.getPrefix();        String sql = """select a.*,p.id as pId,p.keywords pKeywords,p.type as pType, p.pwd as pPwd,p.url pUrl from ${prefix}article a                 left join ${prefix}pancha p on a.id = p.article_id                 where a.id = ?                 order by a.id desc                """;        Object[] params = [id] as Object[]        return commonDao.queryForMap(sql, params);    }}